  var P = window.PPPortal;
  if (!P || !P.api || !window.fetch) { say('We could not send this online. Please use the steps below to send your CV.', true); return; }
  busy(true);
  var cv = fileOf('cf-cv'), ph = fileOf('cf-photo');
