    $$('[data-feed="news-rows"]').forEach(function (list) { sync(list, rows, function (n) { return newsRowInner(el('li'), n); }, newsRowInner, null); });
    $$('[data-feed="news-results"]').forEach(function (list) { sync(list, results, function (n) { return newsRowInner(el('li'), n); }, newsRowInner, null); });
